// TypeScript Version: 4.1

type Unary = ( x: number ) => number;

/**
* Interface for the quantile function of an anglit distribution.
*/
interface Quantile {
	/**
	* Evaluates the quantile function for an anglit distribution with location parameter `mu` and scale parameter `sigma` at a probability `p`.
	*
	* ## Notes
	*
	* -   If `p < 0` or `p > 1`, the function returns `NaN`.
	* -   If `sigma < 0`, the function returns `NaN`.
	*
	* @param p - input value
	* @param mu - location parameter
	* @param sigma - scale parameter
	* @returns evaluated quantile function
	*/
	( p: number, mu: number, sigma: number ): number;

	/**
	* Returns a function for evaluating the quantile function for an anglit distribution with location parameter `mu` and scale parameter `sigma`.
	*
	* @param mu - location parameter
	* @param sigma - scale parameter
	* @returns quantile function
	*/
	factory( mu: number, sigma: number ): Unary;
}

/**
* Anglit distribution quantile function.
*
* @param p - input value
* @param mu - location parameter
* @param sigma - scale parameter
* @returns evaluated quantile function
*/
declare var quantile: Quantile;


// EXPORTS //

export = quantile;
